"""Independent P9-2.3 stress checks, not frozen conformance vectors.

Actual checkout:
  PYTHONPATH=src python P9-2.3-independent-stress-tests.py --repo . --output new.json

Retained isolated audit:
  python P9-2.3-independent-stress-tests.py --isolated p923_audit --output new.json

The isolated mode records its substitutions and does NOT attest the missing
hash-bound current grc_v4_profile.py, package assets, or rfc8785 dependency.
No production code, project authority, or accepted vectors are edited.
"""
from __future__ import annotations
import argparse, ast, copy, dataclasses, hashlib, itertools, json, math, random, re, struct, sys, time, typing
from pathlib import Path
from collections import Counter

parser=argparse.ArgumentParser()
parser.add_argument('--repo',type=Path)
parser.add_argument('--isolated',type=Path)
parser.add_argument('--output',type=Path,required=True)
args=parser.parse_args()
if bool(args.repo)==bool(args.isolated):parser.error('choose --repo or --isolated')
if args.isolated:
 sys.path.insert(0,str(args.isolated.resolve())); import bootstrap as harness
 repo=harness.STAGE
 mode='qualified isolated: exact P9-2.3 modules + exact state/schema/vectors; Node JCS, direct schema provider, earlier uploaded _Record dependency'
else:
 repo=args.repo.resolve();sys.path[:0]=[str(repo/'src'),str(repo)]
 mode='checkout; inspect output source hashes against execution record before asserting exact reproduction'
from pygrc.models import grc_v4_codec as c,grc_v4 as api,grc_v4_step as st,grc_v4_state as state,grc_v4_profile as profile
B=json.loads((repo/'specs/grc-v4-conformance-vectors.json').read_text())
S=json.loads((repo/'specs/grc-v4-contract-schema.json').read_text())
SOURCE='grcv4-state-sha256:'+'a'*64
records=[]

def run(group,case,fn):
 started=time.perf_counter()
 try:
  result=fn()
  records.append({'group':group,'case':case,'status':'pass','observed':result,'seconds':time.perf_counter()-started})
 except Exception as e:
  records.append({'group':group,'case':case,'status':'fail','exception':type(e).__name__,'message':str(e),'seconds':time.perf_counter()-started})

def eq(a,b):
 assert a==b,(a,b)

def raises(fn,exc=(c.V4WireError,c.V4SchemaError,c.V4IdentityError)):
 try:fn()
 except exc as e:return type(e).__name__
 except Exception as e:raise AssertionError('unexpected exception '+type(e).__name__+': '+str(e)) from e
 raise AssertionError('accepted unexpectedly')

def request(dt=0.25,**overrides):
 return {'schema_version':'grcv4-step-request-input-v1','operation_id':'audit:step','dt':dt,'context_value':{'flag':True,'nested':[0,False,None,'é']},'boundary_input':None,'external_source':None}|overrides

def channel(subject='candidate',**overrides):
 return {'schema_version':'grcv4-history-channel-policy-v1','subject':subject,'policy_id':'audit_declared_history_v1','disposition':'not_applicable','source_history_digest':None,'target_initializer_id':None,'information_loss':'none'}|overrides

def migration():
 return {'schema_version':'grcv4-migration-request-v1','operation_id':'audit:migrate','source_state_digest':SOURCE,'target_profile_id':'grcv4-profile-sha256:'+'b'*64,'migration_policy':{'schema_version':'grcv4-migration-policy-v1','policy_id':'typed_bidirectional_profile_migration_v1','resource_policy_id':'identity_resource_transport_v1','target_readmission_policy_id':'full_target_fail_closed_v1'},'history_policy':{'schema_version':'grcv4-history-bundle-policy-v1','candidate':channel(),'carrier':channel('carrier')},'target_context_value':{}}

def raw_dt(token):
 return ('{"schema_version":"grcv4-step-request-input-v1","operation_id":"audit:step","dt":'+token+',"context_value":{},"boundary_input":null,"external_source":null}')

def sha_ascii(payload):
 # Independent expected serializer only for ASCII/string/bool/null/int preimages.
 return hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()).hexdigest()

def atom_payload(operation='audit:step',source=SOURCE,stage='admission',code='invalid_duration'):
 return {'schema_version':'grcv4-failure-receipt-v1','operation_id':operation,'stage':stage,'code':code,'source_state_digest':source,'observed_poststate_digest':source}

# Exact published identity outputs, not generated expectations.
for row in B['canonicalization_vectors']+B['identity_vectors']+B['subdigest_identity_vectors']:
 def f(row=row):
  raw=c.canonical_json_bytes(row['payload'])
  eq(raw,row['canonical_jcs_utf8'].encode());eq(raw.hex(),row['canonical_jcs_utf8_hex'])
  eq(hashlib.sha256(raw).hexdigest(),row['expected_identifier'].split(':')[1])
  eq(c.canonical_json_bytes(c.decode_canonical_json(raw)),raw)
  if row['schema_ref']!='RFC8785':eq(c.payload_identity(row['schema_ref'],row['payload']),row['expected_identifier'])
 run('published_identity',row['vector_id'],f)

# Independent bit preservation + explicit duration branch.
bits=[1,2,0xfffffffffffff,0x10000000000000,0x3ff0000000000000,0x4340000000000000,0x7fefffffffffffff,0x8000000000000001,0xffefffffffffffff]
rng=random.Random(9232026)
while len(bits)<265:
 b=rng.getrandbits(64);v=struct.unpack('>d',b.to_bytes(8,'big'))[0]
 if math.isfinite(v) and v!=0:bits.append(b)
for i,b in enumerate(bits):
 def f(b=b):
  v=struct.unpack('>d',b.to_bytes(8,'big'))[0]
  data=request(v);data['context_value']['binary64']=v
  raw=c.canonical_json_bytes(data)
  q=api.decode_step_request_input(raw,encoding='canonical')
  eq(struct.pack('>d',q.dt),b.to_bytes(8,'big'));eq(q.to_canonical_bytes(),raw)
  a=st.admit_step_request(q,source_state_digest=SOURCE)
  if v<0:
   assert type(a) is st.FailureReceipt
   eq(a.identity_payload.to_payload(),atom_payload())
   eq(a.receipt_id,'grc-receipt-sha256:'+sha_ascii(atom_payload()))
  else:
   assert type(a) is api.GRCV4StepRequest
   eq(struct.pack('>d',a.dt),b.to_bytes(8,'big'))
   expected=copy.deepcopy(data);expected['schema_version']='grcv4-step-request-v1'
   eq(a.to_canonical_bytes(),c.canonical_json_bytes(expected))
 run('binary64_request_composition',f'bits_{i:03d}_{b:016x}',f)

# Exact decimal-underflow boundary and zero representations.
from decimal import Decimal,localcontext
with localcontext() as ctx:
 ctx.prec=1200
 midpoint=Decimal(2)**-1075
 under=[str(midpoint),str(midpoint-Decimal(10)**-1100), '1e-4000','-1e-4000','2e-324','1.234e-999999','-1E-999999']
 over=[str(midpoint+Decimal(10)**-1100),'3e-324','5e-324','4.9406564584124654e-324']
for token in under:
 run('numeric_boundary','underflow_'+token[:45],lambda token=token:raises(lambda:api.decode_step_request_input(raw_dt(token)),c.V4WireError))
for token in over:
 def f(token=token):
  q=api.decode_step_request_input(raw_dt(token));eq(q.dt,5e-324)
 run('numeric_boundary','subnormal_'+token[:45],f)
for token in ['0','0.0','0e-4000','0E+99999','0.00000e-999999']:
 def f(token=token):
  q=api.decode_step_request_input(raw_dt(token));eq(q.dt,0.0)
  assert math.copysign(1,q.dt)>0
  a=st.admit_step_request(q,source_state_digest=SOURCE);assert type(a) is api.GRCV4StepRequest
 run('numeric_boundary','zero_'+token,f)
for token in ['-0','-0.0','-0e-4000','-0e9999','1e309','-1e309','NaN','Infinity','-Infinity','9007199254740992','-9007199254740992']:
 run('numeric_boundary','forbidden_'+token,lambda token=token:raises(lambda:api.decode_step_request_input(raw_dt(token)),c.V4WireError))

# Shape failures take precedence over semantic duration rejection.
bad_shapes=[]
for field in request():
 x=request(-1);del x[field];bad_shapes.append(('missing_'+field,x))
for field,value in [('dt',None),('dt',True),('dt','-1'),('dt',[]),('operation_id',''),('operation_id',1),('context_value',None),('context_value',[]),('boundary_input',False),('external_source',0),('schema_version','grcv4-step-request-v1'),('harness_fault',{}),('target_graph',{}),('topology_event',{}),('commit_id','x')]:
 bad_shapes.append((field+'_'+repr(value),(request(-1)|{field:value})))
bad_shapes.extend([('root_'+repr(x),x) for x in [None,[],False,1,'input']])
for name,data in bad_shapes:
 def f(data=data):
  try:api.decode_step_request_input(json.dumps(data))
  except c.V4DecodeShapeError as e:assert isinstance(e.__cause__,c.V4SchemaError);return type(e).__name__
  raise AssertionError('shape failure was admitted')
 run('shape_before_semantics',name,f)

# Malformed syntax and equivalent duplicate Unicode spellings.
malformed=[b'\xff',b'\xc0\x80',b'\xed\xa0\x80',b'\xef\xbb\xbf{}','{}{}','{"x":1,}',"{'x':1}",'[1,,2]','{"a":1,"a":2}','{"x":{"a":1,"\\u0061":2}}','{"😀":1,"\\ud83d\\ude00":2}','"\\ud800"','"\\udfff"','{"\\ud800":0}','\ufeff{}','{"x":NaN}', '{"x":1e-9999}']
for i,wire in enumerate(malformed):
 run('malformed_wire',str(i),lambda wire=wire:raises(lambda:api.decode_step_request_input(wire),c.V4WireError))
for kind in ['canonical','configuration']:
 for selector in ['step_request','scientific_state_payload','conformance_harness_fault','expansion_event_request_input','../schema','https://example.invalid/x']:
  run('closed_transport',kind+'_'+selector,lambda selector=selector,kind=kind:raises(lambda:c.decode_record_payload(selector,b'{}',encoding=kind),c.V4SchemaError))
for enc in [None,True,'auto','fallback','json',1]:
 run('closed_transport','encoding_'+repr(enc),lambda enc=enc:raises(lambda:api.decode_step_request_input(b'{}',encoding=enc),TypeError))

# Every identity grammar gets bad suffix rejection through the actual pattern implementation.
# Primitive definitions cannot use validate_payload (object records only), so
# these are named validator-unit tests, supplemented by nested integration below.
for name,definition in S['$defs'].items():
 if isinstance(definition,dict) and 'pattern' in definition:
  pattern=definition['pattern']; valid=('0'*64 if name=='sha256_hex' else re.sub(r'^\^','',pattern).split('[',1)[0]+'0'*64)
  # digest_reference has a class rather than a literal prefix.
  if name=='digest_reference':valid='audit-content-sha256:'+'0'*64
  for suffix in ['', '\n','\r','\r\n',' ','\u2028','\u200b','x']:
   def f(pattern=pattern,valid=valid,suffix=suffix):
    errors=list(c._identity_pattern(None,pattern,valid+suffix,None))
    eq(bool(errors),bool(suffix))
   run('identity_pattern_unit',name+'_'+repr(suffix),f)
for field in ['source_state_digest','target_profile_id']:
 for suffix in ['\n','\r','\r\n',' ','\x00','\u2028','\u200b','x']:
  def f(field=field,suffix=suffix):
   data=migration();data[field]+=suffix
   return raises(lambda:api.decode_migration_request(json.dumps(data)),c.V4DecodeShapeError)
  run('nested_identity_rejection',field+'_'+repr(suffix),f)
for suffix in ['\n','\r',' ','\u2028','\x00']:
 for dt in [-1,0,1]:
  run('nested_identity_rejection','source_'+repr((dt,suffix)),lambda suffix=suffix,dt=dt:raises(lambda:st.admit_step_request(api.GRCV4StepRequestInput.from_payload(request(dt)),source_state_digest=SOURCE+suffix)))

# Two separate history channels: schema-valid shape is not migration admission.
for subject,disp,has_source,has_init,loss in itertools.product(['candidate','carrier'],S['$defs']['history_disposition']['enum'],[False,True],[False,True],['none','candidate_history_loss','carrier_history_loss']):
 data=channel(subject,disposition=disp,source_history_digest=('grcv4-history-content-sha256:'+'c'*64) if has_source else None,target_initializer_id='audit_initializer' if has_init else None,information_loss=loss)
 allowed=loss in ['none',subject+'_history_loss'] and (disp!='not_applicable' or (not has_source and not has_init and loss=='none'))
 def f(data=data,allowed=allowed):
  if allowed:
   q=api.ResolvedHistoryChannelPolicy.from_payload(data);eq(q.to_payload(),data)
  else:return raises(lambda:api.ResolvedHistoryChannelPolicy.from_payload(data),c.V4SchemaError)
 run('history_declaration_shape',':'.join(map(str,(subject,disp,has_source,has_init,loss))),f)
for cdisp,kdisp in itertools.product(S['$defs']['history_disposition']['enum'],repeat=2):
 def f(cdisp=cdisp,kdisp=kdisp):
  d=migration();d['history_policy']['candidate']=channel('candidate',disposition=cdisp);d['history_policy']['carrier']=channel('carrier',disposition=kdisp)
  q=api.decode_migration_request(c.canonical_json_bytes(d),encoding='canonical')
  eq(q.history_policy.candidate.disposition,cdisp);eq(q.history_policy.carrier.disposition,kdisp)
  eq(q.to_payload(),d)
 run('history_bundle_roundtrip',cdisp+'_'+kdisp,f)

# Local failure shapes and rehashed invariant violations.
for row in B['atomic_failure_vectors']:
 def f(row=row):
  receipt=row['expected']['failure_receipt'];q=st.FailureReceipt.from_payload(receipt)
  eq(q.to_payload(),receipt)
  eq(q.receipt_id,'grc-receipt-sha256:'+sha_ascii(receipt['identity_payload']))
 run('published_failure_envelopes',row['fixture_id'],f)
for field in ['operation_id','stage','code','source_state_digest','observed_poststate_digest']:
 p=atom_payload();p[field]={'operation_id':'different','stage':'commit','code':'charge_failure','source_state_digest':'grcv4-state-sha256:'+'b'*64,'observed_poststate_digest':'grcv4-state-sha256:'+'b'*64}[field]
 envelope={'schema_version':'grcv4-failure-receipt-envelope-v1','receipt_id':'grc-receipt-sha256:'+sha_ascii(atom_payload()),'identity_payload':p}
 run('receipt_tamper','stale_hash_'+field,lambda envelope=envelope:raises(lambda:st.FailureReceipt.from_payload(envelope)))
for constructor in ['factory','direct']:
 p=atom_payload();p['observed_poststate_digest']='grcv4-state-sha256:'+'b'*64
 envelope={'schema_version':'grcv4-failure-receipt-envelope-v1','receipt_id':'grc-receipt-sha256:'+sha_ascii(p),'identity_payload':p}
 run('receipt_tamper','rehashed_nonatomic_'+constructor,lambda constructor=constructor,envelope=envelope:raises(lambda:(st.FailureReceipt.from_payload(envelope) if constructor=='factory' else st.FailureReceipt(**envelope)),c.V4IdentityError))
for key,value in [('commit_id','grc-commit-sha256:'+'a'*64),('ledger',[]),('committed',False),('solver_disposition',None)]:
 e={'schema_version':'grcv4-failure-receipt-envelope-v1','receipt_id':'grc-receipt-sha256:'+sha_ascii(atom_payload()),'identity_payload':atom_payload(),key:value}
 run('receipt_tamper','extra_'+key,lambda e=e:raises(lambda:st.FailureReceipt.from_payload(e),c.V4SchemaError))
run('enum_parity','stages',lambda:eq(set(typing.get_args(st.OperationStage)),set(S['$defs']['failure_receipt_identity_payload']['properties']['stage']['enum'])))
run('enum_parity','codes',lambda:eq(set(typing.get_args(st.FailureCode)),set(S['$defs']['failure_receipt_identity_payload']['properties']['code']['enum'])))

# Fresh owned copies, repeated values, and opaque context that must stay opaque.
for seed in range(24):
 def f(seed=seed):
  shared={'values':[seed,True,None,{'x':'é'}]}
  d=request(seed/8,context_value={'left':shared,'right':shared},boundary_input={'source':shared},external_source={'add':shared})
  q=api.GRCV4StepRequestInput.from_payload(d);a=st.admit_step_request(q,source_state_digest=SOURCE)
  before=a.to_canonical_bytes();shared['values'].clear();d.clear();q.to_payload().clear()
  eq(a.to_canonical_bytes(),before);assert a.context_value is not q.context_value
 run('ownership',str(seed),f)
for key in ['harness_fault','__reduce__','target_graph','schema_version','implementation_authorized','commit_id']:
 def f(key=key):
  d=request(0,context_value={key:{'enabled':True,'value':[1,2]}})
  q=api.decode_step_request_input(json.dumps(d));a=st.admit_step_request(q,source_state_digest=SOURCE)
  assert type(a) is api.GRCV4StepRequest;eq(a.context_value.to_dict(),d['context_value'])
 run('opaque_context_not_hook',key,f)
for pair in [(True,1),(False,0),({'x':True},{'x':1}),([False],[0])]:
 def f(pair=pair):
  a=api.GRCV4StepRequestInput.from_payload(request(context_value={'x':pair[0]}));b=api.GRCV4StepRequestInput.from_payload(request(context_value={'x':pair[1]}))
  assert a!=b;eq(len({a,b}),2)
 run('json_type_identity',repr(pair),f)

# Environmental failure must stay outside semantic receipt generation.
from unittest.mock import patch
for Exc in [c.V4DependencyError,c.V4AssetError]:
 def f(Exc=Exc):
  with patch.object(c,'load_contract_schema',side_effect=Exc('audit provider unavailable')):
   return raises(lambda:api.decode_step_request_input(json.dumps(request(-1))),Exc)
 run('environmental_failures',Exc.__name__,f)

# No executable facade/support or unintended import of numerical/lifecycle owners.
def scope_check():
 assert not hasattr(api,'GRCV4');eq(profile.list_supported_profiles(),frozenset())
 loaded=[n for n in sys.modules if n.startswith('pygrc.models.')]
 assert not any(any(t in n for t in ('candidate_a','candidate_c','realizations','lifecycle','grc_9')) for n in loaded),loaded
run('scope_ceiling','no_model_or_profile_promotion',scope_check)

counts={g:dict(Counter(r['status'] for r in records if r['group']==g)) for g in sorted({r['group'] for r in records})}
summary={'mode':mode,'python':sys.version,'node':None,'tests':len(records),'pass':sum(r['status']=='pass' for r in records),'fail':sum(r['status']=='fail' for r in records),'groups':counts,'source_hashes':{},'results':records}
for module in [api,st,c,state,profile]:
 p=Path(module.__file__);summary['source_hashes'][module.__name__]={'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(json.dumps(summary,indent=2,ensure_ascii=True)+'\n')
print(json.dumps({k:v for k,v in summary.items() if k not in ('results','source_hashes')},indent=2))
for r in records:
 if r['status']=='fail':print('FAIL',r['group'],r['case'],r['exception'],r['message'][:400])
sys.exit(bool(summary['fail']))

